import{_ as s,O as a,o as i,c as r,a as o,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const b=JSON.parse('{"title":"D.06　人性、演化、习惯与行动能力","description":"","frontmatter":{"title":"D.06　人性、演化、习惯与行动能力","xkChars":673,"xkLessons":{"D.06":{"title":"D.06　人性、演化、习惯与行动能力","lead":"一个人确实签了字，不代表他能安全地说不；一种行为长期稳定，也不代表它写在基因里永远不变。解释人的行动，需要把形成、处境、选择和责任拆开，再按材料连接。","explanation":["原文定位：第4609—4624行；原文锚点 section-d-06；短引文：‘受约束者确实采取行动、能够安全拒绝、有效同意以及应负何责，仍是四种判断。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","当下功能、历史适应、漂变、文化传播、个人意图和福利后果回答不同问题。当前有益的行为可能起源于其他条件，后来才获得这一功能；被保留的文化形式可能涉及传播、约束或路径延续，不等于每个成员赞成。福利后果讲谁受益受损，个人意图讲行动者以什么为理由，不能从好结果倒推善意，也不能从历史存在推出应继续保留。","合作可能由亲缘、互惠、声誉、伙伴选择或制度约束产生。分析时应具体指出谁能观察行为、谁随后回应、何种收益代价被预期、由谁承担实际成本。相似的合作表面不能判定同一机制；没有回应者或信息渠道时，不能仅用声誉二字解释一切。多种机制可以并存，但需要分别说明其材料，而不是任意切换故事以保证结论不败。","人格差异可以表现为条件性的稳定倾向，慢变化却不等于遗传、不变或本质。相似行为反复出现，可能由习惯、环境选择、机会、情境提示和身体技能共同形成；跨情境记录也要查谁进入了哪些场景、测量是否可比。先检查情境是调查次序，不是预先宣判人格没有作用。若比较人格、情境及交互，应给予相称信息与评价条件，不能用丰富情境资料对比粗糙人格标签后宣布理论胜负。","一般学习可由练习、表现及形成过程支持，例如技能变化已写入当前状态。G3则窄问在指定当前表示之外，历史还提供什么增量。技能学习已经发生与额外历史增量未见可以同时成立；不满足窄合同不等于没有学习。环境机会与身体实践也不能被还原为抽象激励分数，需保留实际能做什么、知道什么和承担什么。","受约束的行动仍可能是行动者作出的决定，但不因此成为自由同意。应分开实际行为、当时信息、局部控制、可拒绝选项、后果与归责。原文员工在可信惩罚下签记录是教学例：签署确实发生，安全拒绝可能不具备，有效同意须另核；设计者、主管与获益者可能分别在规则、命令和收益链承担不同责任。不能用“他自己选择”抹掉控制链，也不能把有约束等同完全没有任何行动能力。","高代价不自动证明真诚、爱或认同。代价可能来自强制、误判、没有替代选择、声誉激励或其他原因；需要看实际情境与可反驳材料。低代价的善意也不因未满足HV11正式合同就失去日常价值。正式结果登记与普通人的帮助、关怀、意义不是一套价值排名，不能让高成本成为判断爱或道德地位的通用凭证。","情境、人格及交互的解释量可能重叠。若先把共同部分全部记给情境，再检查人格剩余为零，最多说明在该表示和排序下没有额外增量，不能证明人格相关变量不存在；反过来先记给人格再否定情境同样错误。需要说明共同解释、独立增量与交互的区别，避免把统计分配规则当成关于人的本体结论。","处理带来的行为差异归于所操弄的完整条件包，不能擅自拆成某一成分的独立效应。催促指令可能同时改变可用时间、责任预期、紧张和注意，而实验即使有组间差异，也不自动逐项识别这些中介。若要回答某个成分的作用，需要额外设计与材料。比较也不允许把被观察到的群体差异升级为对任何个人的固定性格裁决。","自然选择与社会筛选都不直接生成应当。某形式成功存续可以成为因果研究对象，不因此获得规范正当性；某行为被制度奖励，也不证明它值得提倡。对责任的判断同样要公开规范前提、控制能力、信息和具体后果，不靠演化故事或受约束者的动作事实完成全部归责。","八个专题入口依次涉及人性与情境论、选择适应漂变、文化演化与双重继承、合作机制、人格情境交互、自由责任与能力、习惯身体环境、超越激励的行动解释。Boyd与Richerson等名字指向研究线索，不意味着本节把整个文化演化研究当作未经区分的人性公理。最强反方担心强调情境就让所有人免责；回应是归责要更精确地分配到能力、信息、控制和设计链，而不是通过一种极端替代另一种。"],"distinctions":[{"leftTitle":"当前功能有益","leftText":"行为目前具有某种好后果。","rightTitle":"历史因该功能产生","rightText":"起源机制另需历史与比较材料。"},{"leftTitle":"条件稳定倾向","leftText":"在一定条件下反复出现的行为模式。","rightTitle":"遗传不变本质","rightText":"慢变不提供该结论，环境与实践仍需考虑。"},{"leftTitle":"确实作出行动","leftText":"某人执行了动作并可能有局部控制。","rightTitle":"安全拒绝与有效同意","rightText":"还要看替代选项、压力、信息与授权条件。"},{"leftTitle":"条件包效应","leftText":"操弄全部安排产生的差异。","rightTitle":"单成分独立作用","rightText":"需要额外区分设计，不能任意拆解归因。"},{"leftTitle":"一般学习与善意","leftText":"可按实际任务和日常意义描述。","rightTitle":"G3或HV11正式资格","rightText":"只约束其窄合同，不是全部知识与人的价值门槛。"}],"boundaries":["不得用慢变行为推定遗传、本质或无法改变，也不对真实人物作人格诊断。","情境优先调查不等于情境永久解释优先，比较须信息与条件相称。","高代价不证明真诚爱认同，低代价帮助不因窄合同未满足失去价值。","真实动作不自动证明安全拒绝、有效同意或全部责任。","本讲未开展真人实验、安排欺骗或施加惩罚；历史研究仅作原报告限定解读。"],"questions":["为什么行为现在有用不证明起源就是为了这个功能？","真实行动与自由同意能否一真一假？","同列算例P加到S后无增量能说明什么？","实验催促指令有差异，能否直接称纯粹时间效应？"],"diagramPath":"/reading-assets/S-D-06/figures/section-d-06.png","caseLinks":[{"title":"真实原始研究：催促条件与帮助行为的有限比较","href":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/darley_batson_1973_-_from_jerusalem_to_jericho.pdf"}],"caseNotes":[{"title":"真实原始研究：催促条件与帮助行为的有限比较","text":"Darley与Batson1973年报告的实验实际在1970年12月14—16日进行。原稿说明47人进入实验安排、7人数据因程序污染或怀疑情境未纳入，分析40人；催促程度通过不同指令操弄，作者报告其与帮助反应有差异。这个结果适合检查情境条件，不能证明所有人格因素不存在或单独识别纯时间压力。","sourceLabel":"Darley & Batson, JPSP27(1),100—108，1973原刊扫描","sourceUrl":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/darley_batson_1973_-_from_jerusalem_to_jericho.pdf","sourceLocator":"印刷p102 Subjects；p103 Scheduling及脚注3；pp103—104 Variable2:Hurry；pp104—105 Overall Helping Behavior","boundary":"小样本神学院学生及具体情境；原稿脚注3披露分配错误增加中度催促人数。这里不重估统计、不宣称普遍复现、不采用未识别的人格本质或单中介结论。","href":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/darley_batson_1973_-_from_jerusalem_to_jericho.pdf"}],"sourceRefs":[{"section":"D.06","start_line":4609,"end_line":4624,"startLine":4609,"endLine":4624}],"outputId":"section-d-06","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["区分行为的当前功能、历史形成、传播、意图和福利，逐问题寻找材料。","对合作与稳定倾向说明观察回应通道、机会、练习及跨情境选择测量。","分开实际行动、安全拒绝、有效同意与责任，追踪设计者主管受益者的不同控制位置。","比较人格情境时公开重叠和增量，不将条件包效应拆成未识别单成分。","承认一般学习与低代价善意可有价值，同时不由演化存续、成本或效果生成规范授权。"],"teachingExamples":[{"title":"原文教学例展开：可信惩罚下的签署","text":"假想员工被告知不签记录就受可信惩罚，随后亲手签字。可确认签署行为；能否安全拒绝和是否有效同意另判。组织设计者设置规则、主管施压、获益者取得收益的责任可能不同，不能用签名把整条控制链压成员工一人的责任。","assumptions":"沿原文教学例，无真实员工或处罚。","boundary":"不作法律责任裁决，实际归责需适用规范与事实。"},{"title":"数学教学构造：重叠不是一方不存在","text":"设四条构造记录中情境编码S=(0,0,1,1)、倾向代理P=(0,0,1,1)、行为Y=(0,0,1,1)。只用S即可完全拟合Y，加入P无额外拟合增益；先用P再加S同样如此。因此增量零不能区分究竟哪一变量具有独立现实机制，更不能断言另一类因素不存在。","assumptions":"三个序列完全同列只是形式反例，不是人格测量数据或因果模型。","boundary":"不估计真实人格情境作用；真实识别需独立变异、测量及适当设计。"},{"title":"教学构造：低代价善意仍有价值","text":"假想同事顺路帮人带回一份所需资料，没有重大自我牺牲，却确实减轻对方一次奔波。可按日常帮助描述，不必先证明高成本或HV11正式结果；若要进一步声称改变长期关系或制度反馈，仍需对应材料。","assumptions":"人物与帮助为教学假设。","boundary":"不从一个小帮助推断人格本质或长期关系已修复。"}],"counterexamples":[{"identity":"constructed_boundary","text":"这种习惯多年不变，所以必然是遗传且不能改变。","effect":"稳定性不足以区分练习、环境选择、机会与遗传等机制。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"人格代理在先纳入情境后无增量，因此人格完全不存在。","effect":"共同解释量分配依赖表示与顺序，形式同列例反驳该推断。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"员工自己签名，制度设计者和主管就不再有责任。","effect":"行动事实不抹去拒绝条件与分层控制责任。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么行为现在有用不证明起源就是为了这个功能？","answer":"当前后果与历史形成是不同问题，可能存在功能变化及其他形成过程。","basis":"本节原文及上述公开推导"},{"question":"真实行动与自由同意能否一真一假？","answer":"可以，受约束者可有局部行动能力但缺安全拒绝条件，需分开判断。","basis":"本节原文及上述公开推导"},{"question":"同列算例P加到S后无增量能说明什么？","answer":"在该数据表示下P没有额外拟合信息，不能识别人格与情境谁不存在或谁有因果。","basis":"本节原文及上述公开推导"},{"question":"实验催促指令有差异，能否直接称纯粹时间效应？","answer":"不能自动，指令可能同时改变多项条件；单成分或中介需要额外识别。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-06/figures/section-d-06.png","alt":"功能／形成／传播，意图／福利分开；人格条件倾向，慢变≠遗传或本质，情境与练习也须核；四种判断，真实行动／安全拒绝，有效同意／责任；重叠解释不独占，增量零≠因素不存在；条件包效应，不拆成未识别单成分；成本不证明爱与真诚，演化筛选不生成应当，一般学习仍可成立。作者依D.06绘制；原文员工例及同列序列为教学构造，不诊断真实人格。","caption":"作者依D.06绘制；原文员工例及同列序列为教学构造，不诊断真实人格。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换是否能安全拒绝、资料是否同列、操弄是否多成分，显示对应推断范围和责任未决。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"具体原始研究用于约束条件包与人格解释的外推，未复制实验或把受试者行为作道德标签。"},"openQuestions":["未复核该研究原始个体数据、长期复现及全部人格测量细节；只读所列方法结果段。","未取得06.01—06.08对应全部研究原稿，不能复原完整思想采纳史。"],"taskId":"S-D-06","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4609—4624行；每节精确范围见sourceRefs","claim_support":["D.06：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"darley-batson1973","title":"From Jerusalem to Jericho: A Study of Situational and Dispositional Variables in Helping Behavior","url":"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/darley_batson_1973_-_from_jerusalem_to_jericho.pdf","source_type":"primary","version_or_date":"JPSP27(1),100—108，1973；研究实施1970-12-14—16","locator":"pp102—105：Subjects；Scheduling及脚注3；Variable2:Hurry；Overall Helping Behavior","claim_support":["原研究的样本筛选、实验日期、催促指令和限定帮助结果"],"limits":["未复核原始数据、不声称全人格无效或单独时间机制成立；原稿披露随机分配差错，适用人群与情境有限。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-06/lecture.md","sourcesPath":"/reading-assets/S-D-06/sources.json","sourceSlicePath":"/reading-assets/S-D-06/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-06/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-06.md","filePath":"theory/appendix-d/d-06.md"}'),d={name:"theory/appendix-d/d-06.md"};function c(p,e,u,_,f,m){const t=a("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=o("",1)),n(t,{section:"D.06"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const y=s(d,[["render",c]]);export{b as __pageData,y as default};
